package com.notificationpanel.rules;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Objects;
import java.util.Set;
import java.util.UUID;

public final class RuleCodec
{
	/**
	 * How long one stored configuration value may be.
	 *
	 * <p>Declared here because this is where an over-long value is refused on read. The store
	 * checks it before writing and the legacy migrator before importing, both through this
	 * constant, so nothing can be written that this would then reject.</p>
	 */
	static final int MAX_CONFIG_LENGTH = 262_144;

	/**
	 * The oldest stored version that still decodes.
	 *
	 * <p>Every profile written before per-rule visibility holds a version 1 document, so refusing
	 * that version would empty the editor and hide the user's rules behind a reset. One is upgraded
	 * in memory instead; the upgraded form reaches configuration on the next ordinary save.</p>
	 */
	private static final int OLDEST_SUPPORTED_SCHEMA_VERSION = 1;

	/** The first version that could store a per-rule visibility override. */
	private static final int VISIBILITY_SCHEMA_VERSION = 2;

	private final Gson gson;

	public RuleCodec(Gson gson)
	{
		this.gson = Objects.requireNonNull(gson, "gson").newBuilder().serializeNulls().create();
	}

	public String encode(RuleDocument document)
	{
		Objects.requireNonNull(document, "document");
		DocumentDto dto = new DocumentDto();
		// Stamped from what the rules actually use, not from the document's own version, so a
		// profile where nobody sets Visibility keeps writing version 1. Older builds reject any
		// version they do not know outright -- "rule data is corrupt; using no rules until it is
		// reset" -- so writing 2 unconditionally would put every user one rollback away from that
		// banner to buy a field none of their rules use.
		dto.schemaVersion = usesVisibility(document)
			? VISIBILITY_SCHEMA_VERSION : OLDEST_SUPPORTED_SCHEMA_VERSION;
		dto.migrationWarnings = new ArrayList<>(document.getMigrationWarnings());
		dto.rules = new ArrayList<>();
		for (NotificationRule rule : document.getRules())
		{
			RuleDto ruleDto = new RuleDto();
			ruleDto.id = rule.getId().toString();
			ruleDto.name = rule.getName();
			ruleDto.enabled = rule.isEnabled();
			ruleDto.pattern = rule.getPattern();
			ruleDto.backgroundColor = rule.getBackgroundRgb() == null
				? null : String.format("#%06X", rule.getBackgroundRgb());
			ruleDto.opacityPercent = rule.getOpacityPercent();
			// Written as a pair on purpose. A build older than the sidebar log ignores the
			// unknown string -- Gson drops members it has no field for -- and reads the
			// boolean, so SIDEBAR degrades there to "kept off the panel", the closest thing a
			// build with no log can mean by it. Writing both is also what lets schemaVersion
			// stay 2, so no rollback meets the corrupt-data banner over this field.
			ruleDto.visible = rule.getVisibility() == null
				? null : rule.getVisibility() == Visibility.SHOW;
			ruleDto.visibility = rule.getVisibility() == null
				? null : rule.getVisibility().name();
			ruleDto.migrationNote = rule.getMigrationNote();
			dto.rules.add(ruleDto);
		}
		return gson.toJson(dto);
	}

	/** Whether any rule carries the one field that a build older than this one cannot read. */
	private static boolean usesVisibility(RuleDocument document)
	{
		for (NotificationRule rule : document.getRules())
		{
			if (rule.getVisibility() != null)
			{
				return true;
			}
		}
		return false;
	}

	public DecodeResult decode(String encoded)
	{
		if (encoded != null && encoded.length() > MAX_CONFIG_LENGTH)
		{
			return DecodeResult.failure(
				"Structured rule data exceeds " + MAX_CONFIG_LENGTH + " characters.");
		}

		DocumentDto dto;
		try
		{
			dto = gson.fromJson(encoded, DocumentDto.class);
		}
		catch (JsonParseException exception)
		{
			return DecodeResult.failure("Structured rules are not valid JSON.");
		}
		if (dto == null)
		{
			return DecodeResult.failure("Structured rules are not valid JSON.");
		}
		if (dto.schemaVersion < OLDEST_SUPPORTED_SCHEMA_VERSION
			|| dto.schemaVersion > RuleDocument.CURRENT_SCHEMA_VERSION)
		{
			return DecodeResult.failure("Unsupported structured-rule schema version: "
				+ dto.schemaVersion + ".");
		}
		if (dto.migrationWarnings == null)
		{
			return malformed("migration warnings array is missing.");
		}
		for (String warning : dto.migrationWarnings)
		{
			if (warning == null)
			{
				return malformed("migration warning entries must not be null.");
			}
		}
		if (dto.rules == null)
		{
			return malformed("rules array is missing.");
		}
		if (dto.rules.size() > RuleSet.MAX_RULES)
		{
			return malformed("a document may contain at most " + RuleSet.MAX_RULES + " rules.");
		}

		List<NotificationRule> rules = new ArrayList<>();
		Set<UUID> ids = new HashSet<>();
		for (RuleDto ruleDto : dto.rules)
		{
			if (ruleDto == null)
			{
				return malformed("rules must not contain a null rule.");
			}

			UUID id;
			try
			{
				id = UUID.fromString(ruleDto.id);
			}
			catch (IllegalArgumentException | NullPointerException exception)
			{
				return malformed("rule UUID is missing or invalid.");
			}
			if (!id.toString().equalsIgnoreCase(ruleDto.id))
			{
				return malformed("rule UUID is missing or invalid.");
			}
			if (!ids.add(id))
			{
				return malformed("rule UUIDs must be unique.");
			}
			if (ruleDto.name == null)
			{
				return malformed("rule name must not be null.");
			}
			if (ruleDto.pattern == null)
			{
				return malformed("rule pattern must not be null.");
			}

			Integer backgroundRgb = null;
			if (ruleDto.backgroundColor != null)
			{
				if (!isRgbColor(ruleDto.backgroundColor))
				{
					return malformed("rule background color must use #RRGGBB.");
				}
				backgroundRgb = Integer.parseInt(ruleDto.backgroundColor.substring(1), 16);
			}
			if (ruleDto.opacityPercent != null
				&& (ruleDto.opacityPercent < 0 || ruleDto.opacityPercent > 100))
			{
				return malformed("rule opacity must be between 0 and 100.");
			}

			NotificationRule rule = new NotificationRule(id, ruleDto.name, ruleDto.enabled,
				ruleDto.pattern, backgroundRgb, ruleDto.opacityPercent,
				readVisibility(ruleDto), ruleDto.migrationNote);
			rules.add(dto.schemaVersion < VISIBILITY_SCHEMA_VERSION
				? restoreLegacyHide(rule) : rule);
		}

		return DecodeResult.success(new RuleDocument(RuleDocument.CURRENT_SCHEMA_VERSION,
			dto.migrationWarnings, rules));
	}

	/**
	 * Reads a rule's visibility, preferring the three-valued field over the boolean beside it.
	 *
	 * <p>An unrecognised string falls through to the boolean rather than failing the document. A
	 * value invented by a later build would otherwise strand the whole rule list behind a reset,
	 * and the boolean is guaranteed to be there: this codec never writes one without the other.</p>
	 */
	private static Visibility readVisibility(RuleDto ruleDto)
	{
		if (ruleDto.visibility != null)
		{
			for (Visibility candidate : Visibility.values())
			{
				if (candidate.name().equals(ruleDto.visibility))
				{
					return candidate;
				}
			}
		}
		if (ruleDto.visible == null)
		{
			return null;
		}
		return ruleDto.visible ? Visibility.SHOW : Visibility.HIDE;
	}

	/**
	 * Gives a rule back the hide the 2.0 import took away.
	 *
	 * <p>That import had nowhere to put a legacy {@code hide} token, so it recorded a problem and
	 * turned the rule off. The note is the only record of what the user asked for, so it is read
	 * back here: the rule hides again, and the sentence is dropped because there is no longer
	 * anything for the user to do about it. Only that sentence goes -- a rule whose pattern also
	 * failed to convert still has a real problem and stays off with it.</p>
	 */
	private static NotificationRule restoreLegacyHide(NotificationRule rule)
	{
		String note = rule.getMigrationNote();
		if (note == null || !note.startsWith(LegacyRuleMigrator.PROBLEM_NOTE_PREFIX)
			|| !note.contains(LegacyRuleMigrator.LEGACY_HIDE_PROBLEM))
		{
			return rule;
		}

		String problems = note.substring(LegacyRuleMigrator.PROBLEM_NOTE_PREFIX.length())
			.replace(LegacyRuleMigrator.LEGACY_HIDE_PROBLEM, "")
			.replaceAll("\\s{2,}", " ")
			.trim();
		boolean soleProblem = problems.isEmpty();
		return new NotificationRule(rule.getId(), rule.getName(),
			soleProblem || rule.isEnabled(), rule.getPattern(), rule.getBackgroundRgb(),
			rule.getOpacityPercent(), Visibility.HIDE,
			soleProblem ? null : LegacyRuleMigrator.PROBLEM_NOTE_PREFIX + problems);
	}

	private static boolean isRgbColor(String value)
	{
		if (value.length() != 7 || value.charAt(0) != '#')
		{
			return false;
		}
		for (int index = 1; index < value.length(); index++)
		{
			char character = value.charAt(index);
			if (!((character >= '0' && character <= '9')
				|| (character >= 'A' && character <= 'F')
				|| (character >= 'a' && character <= 'f')))
			{
				return false;
			}
		}
		return true;
	}

	private static DecodeResult malformed(String reason)
	{
		return DecodeResult.failure("Structured rule data is malformed: " + reason);
	}

	public static final class DecodeResult
	{
		private final RuleDocument document;
		private final String error;

		private DecodeResult(RuleDocument document, String error)
		{
			this.document = document;
			this.error = error;
		}

		private static DecodeResult success(RuleDocument document)
		{
			return new DecodeResult(document, null);
		}

		private static DecodeResult failure(String error)
		{
			return new DecodeResult(null, error);
		}

		public boolean isSuccess()
		{
			return document != null;
		}

		public RuleDocument getDocument()
		{
			return document;
		}

		public String getError()
		{
			return error;
		}
	}

	private static final class DocumentDto
	{
		private int schemaVersion;
		private List<String> migrationWarnings;
		private List<RuleDto> rules;
	}

	private static final class RuleDto
	{
		private String id;
		private String name;
		private boolean enabled;
		private String pattern;
		private String backgroundColor;
		private Integer opacityPercent;
		private Boolean visible;
		private String visibility;
		private String migrationNote;
	}
}

