		verify(state, never()).clear();

		plugin.shutDown();
		verify(overlayManager).remove(overlay);
		// Still nothing: shutDown runs on the EDT and the overlay may be mid-render on the
		// client thread, which iterates the same collection.
		verify(state, never()).clear();
		runClientTasks();
		verify(state).clear();
		flushEdt();
	}

